-- Bridge from the published 127 (SOURCE_MAP section 3) to this lane's count. Analysis only: reads the source-map lane's scratch pair files
-- (controller storage), so check.py does not depend on it. Unit: PIC-18 organization rows with unknown process (322).
CREATE TEMP TABLE unk AS SELECT * FROM read_csv('/Users/johnswanson/.bb/thread-storage/thr_9i2c6byhcz/2026-11-06-atlas/source-map-2026-11-22/scratch/pic18_unknown_orgs.csv', header=true) WHERE proc_unknown=1;
CREATE TEMP TABLE nx AS
  SELECT p.org_id,'1 osha_ita (filed by the establishment)' src, i.naics_code naics FROM read_parquet('/Users/johnswanson/.bb/thread-storage/thr_9i2c6byhcz/2026-11-06-atlas/source-map-2026-11-22/scratch/pairs/osha_ita.parquet') p JOIN osha_ita i USING(src_path,src_row) WHERE p.name_ok AND p.in_pic18
  UNION ALL SELECT p.org_id,'2 sam primary NAICS (entity registration)', s.primary_naics FROM read_parquet('/Users/johnswanson/.bb/thread-storage/thr_9i2c6byhcz/2026-11-06-atlas/source-map-2026-11-22/scratch/pairs/sam_passing_the_r_sam_filter.parquet') p JOIN sam s USING(src_path,src_row) WHERE p.name_ok AND p.in_pic18
  UNION ALL SELECT p.org_id,'3 osha inspection (assigned at inspection)', i.NAICS_CODE FROM read_parquet('/Users/johnswanson/.bb/thread-storage/thr_9i2c6byhcz/2026-11-06-atlas/source-map-2026-11-22/scratch/pairs/osha_inspection.parquet') p JOIN osha_inspection i USING(src_path,src_row) WHERE p.name_ok AND p.in_pic18
  UNION ALL SELECT p.org_id,'4 icis-air facility record', trim(n) FROM read_parquet('/Users/johnswanson/.bb/thread-storage/thr_9i2c6byhcz/2026-11-06-atlas/source-map-2026-11-22/scratch/pairs/echo_air.parquet') p JOIN echo_air a USING(src_path,src_row), unnest(string_split(a.NAICS_CODES, ',')) t(n) WHERE p.name_ok AND p.in_pic18
  UNION ALL SELECT p.org_id,'5 frs facility naics', n.NAICS_CODE FROM read_parquet('/Users/johnswanson/.bb/thread-storage/thr_9i2c6byhcz/2026-11-06-atlas/source-map-2026-11-22/scratch/pairs/echo_frs.parquet') p JOIN echo_frs f USING(src_path,src_row) JOIN read_parquet('/Users/johnswanson/.bb/thread-storage/thr_9i2c6byhcz/2026-11-06-atlas/source-map-2026-11-22/scratch/lake_out/echo/echo_frs_naics.parquet') n ON n.REGISTRY_ID=f.registry_id WHERE p.name_ok AND p.in_pic18;
CREATE TEMP TABLE c AS SELECT DISTINCT n.org_id, n.src, trim(n.naics) naics FROM nx n JOIN unk u USING(org_id) WHERE regexp_matches(trim(n.naics),'^[0-9]{6}$') AND trim(n.naics) NOT IN ('000000','999999');
CREATE TEMP TABLE t1(naics varchar); INSERT INTO t1 VALUES ('326211'),('326212'),('326220'),('325991'),('325510'),('325520'),('325910'),('333511'),('326140'),('326150');
CREATE TEMP TABLE t2(naics varchar); INSERT INTO t2 VALUES ('325211'),('325212'),('326121'),('326160'),('326130');
SELECT src, count(DISTINCT org_id) orgs_with_6digit_code, count(DISTINCT org_id) FILTER (WHERE naics IN (SELECT naics FROM t1)) orgs_with_T1_code, count(DISTINCT org_id) FILTER (WHERE naics IN (SELECT naics FROM t2)) orgs_with_T2_code FROM c GROUP BY 1 ORDER BY 1;
SELECT 'union of the five sources' src, count(DISTINCT org_id) orgs_with_6digit_code, count(DISTINCT org_id) FILTER (WHERE naics IN (SELECT naics FROM t1)) orgs_T1, count(DISTINCT org_id) FILTER (WHERE naics IN (SELECT naics FROM t2)) orgs_T2 FROM c;
SELECT 'filed by the establishment or entity (sources 1+2)' src, count(DISTINCT org_id), count(DISTINCT org_id) FILTER (WHERE naics IN (SELECT naics FROM t1)), count(DISTINCT org_id) FILTER (WHERE naics IN (SELECT naics FROM t2)) FROM c WHERE src LIKE '1%' OR src LIKE '2%';
SELECT 'sources 3+4+5 only (not filed by the establishment)' src, count(DISTINCT org_id), count(DISTINCT org_id) FILTER (WHERE naics IN (SELECT naics FROM t1)), count(DISTINCT org_id) FILTER (WHERE naics IN (SELECT naics FROM t2)) FROM c WHERE org_id NOT IN (SELECT org_id FROM c WHERE src LIKE '1%' OR src LIKE '2%');
